const input = Array.isArray($json) ? $json : [$json];
return input.map((job) => {
  const eligible = job.reviewEligible === true && `${job.technicianStatus ?? ''}`.toLowerCase().includes('happy');
  const optOut = job.reviewOptOut === true;
  const subVertical = `${job.subVertical ?? 'other'}`.toLowerCase();
  const reviewLinkBySubVertical = {
    plumbing: 'https://g.page/r/plumber-review-placeholder',
    electrical: 'https://g.page/r/electrician-review-placeholder',
    landscaping: 'https://www.houzz.com/professionals/landscape/review-placeholder',
    'pest-control': 'https://g.page/r/pest-control-review-placeholder',
    'tree-service': 'https://g.page/r/tree-service-review-placeholder',
    other: 'https://g.page/r/home-services-review-placeholder'
  };
  return { json: { ...job, subVertical, reviewAction: (eligible && !optOut) ? 'send-review-request' : 'manager-follow-up-first', reviewLink: (eligible && !optOut) ? reviewLinkBySubVertical[subVertical] ?? reviewLinkBySubVertical.other : null } };
});
